/* ---------- Project plan ---------- */
function sCurve(id){const P=plan(S.ims.scen,ulist()),B=baseCalc(P.list||TASKS),w=PTASKS(id).filter(t=>!t.ms).map(t=>({t,w:(t.res.reduce((a,r)=>a+r[1],0)||1)*t.dur})),tot=w.reduce((a,x)=>a+x.w,0)||1;
 const at=(R,wn)=>w.reduce((a,x)=>a+x.w*Math.max(0,Math.min(1,(wn-R.R[x.t.id].es)/Math.max(1,R.R[x.t.id].ef-R.R[x.t.id].es))),0)/tot*100;
 const idx=MONTHS.map(m=>WD.findIndex(t=>{const d=new Date(t);return d.getUTCFullYear()===m[1]&&d.getUTCMonth()===m[2]}));idx.push(wdOf("2027-04-01"));const ends=idx.slice(1).map(x=>x-1);
 const base=ends.map(e=>Math.round(at(B,e))),cur=ends.map(e=>Math.round(at(P,e)));const ti=ends.findIndex(e=>e>=TODAY);
 return {labels:MONTHS.map(m=>m[0]),base,cur:cur.slice(ti),ti,ev:Math.round(evm(P,id).ev*100)}}
function planPicker(id){const U=UPROJ();if(U.length<=6)return `<div class="recchips">${U.map(p=>`<button class="chip" data-planproj="${p.id}" aria-pressed="${p.id===id}">${esc(p.short)}</button>`).join("")}</div>`;
 if(window.PICKER&&window.LISTS)return `<div class="gx-sel"><span class="muted small">Project</span>${PICKER.html({id:"plan_proj",label:"Project",noun:"projects",source:"projects",value:id,recent:"projects",onPick:v=>{if(!v)return;S.planProj=v;audit("picked project plan",v);render()}})}</div>`;
 return `<label class="gx-sel"><span class="muted small">Project</span><select class="fin" data-planselect aria-label="Project">${U.map(p=>`<option value="${p.id}" ${p.id===id?"selected":""}>${esc(p.id+" "+p.n)}</option>`).join("")}</select></label>`}
_R.plan=()=>{if(PDTV.TEN())return tvPlan();if(!pr(S.planProj))S.planProj="PR1";const id=S.planProj,pj=pr(id),O=S.ims,P=plan(O.scen,ulist());syncSpi();const e=evm(P,id),fin=projFin(P,id),bf=projFin(baseCalc(P.list||TASKS),id),d=fin-bf,sc=sCurve(id),crit=PTASKS(id).filter(t=>P.R[t.id].fl<=0&&P.R[t.id].ef>0&&t.pct<100&&!t.ms),paid=pj.paid/pj.bac,rs=rollup(P),a=rs.PJ[id]||{};
 const story=`${esc(pj.n)} finishes <b>${fmtD(fin1(P,id),1)}</b>, <b>${lateTxt(d)}</b>. It is <b>${a.pct||sc.ev}%</b> done against <b>${Math.round(e.pv*100)}%</b> planned, and <b>${crit.length}</b> task${crit.length===1?"":"s"} ${crit.length===1?"has":"have"} no float${crit[0]?`, starting with ${esc(crit[0].n.toLowerCase())}`:""}.`;
 const chain=`<div class="card glass"><div class="cardhead"><h3>Critical path</h3><span class="muted small">Tasks with zero float, in order</span></div><div class="chainrow">${crit.sort((x,y)=>P.R[x.id].es-P.R[y.id].es).map((t,i)=>`${i?'<i class="arr"></i>':""}<button class="chip" data-task="${t.id}">${esc(t.n)}</button>`).join("")||'<span class="muted">Nothing critical is left.</span>'}</div></div>`;
 const curve=`<div class="card glass"><div class="cardhead"><div><h3>Percent complete over time</h3><span class="muted small" data-role="story">The dashed line is where we are heading. The gap to the grey line is the schedule slip.</span></div>${fchip("m_spi")}</div>${lineChart(sc.labels,[{vals:sc.base,color:col("--faint"),w:2,dash:true},{vals:sc.cur,color:col("--p4"),area:true,start:sc.ti}],{max:100,ticks:4,fmt:v=>v+"%",alt:"Planned against forecast percent complete"})}<div class="legend-row"><span><i class="sw" style="background:var(--faint)"></i>Baseline</span><span><i class="sw" style="background:var(--p4)"></i>Current forecast</span><span>Paid ${Math.round(paid*100)}% of the ${K$(pj.bac)} budget</span></div></div>`;
 const tiles=`<div class="grid g4" style="margin-bottom:18px">${tl("Finish",fmtD(fin1(P,id)),lateTxt(d),pcls(d))}${tl("Schedule performance",e.pv>.05?e.spi.toFixed(2):"n/a","Earned ÷ planned · target 0.95",e.spi>=.95||e.pv<=.05?"good":"warn")}${tl("Done",(a.pct||sc.ev)+"%","Planned "+Math.round(e.pv*100)+"%",(a.pct||sc.ev)>=e.pv*100-3?"good":"warn")}${tl("Budget used",Math.round(paid*100)+"%",K$(pj.paid)+" of "+K$(pj.bac),paid>(a.pct||0)/100+.25?"warn":"good")}</div>`;
 const sel={projects:[id],kinds:null};const pk=imsPickers("plan",{noProj:true});sel.kinds=pk.kinds;const rows=schedLines(P,Object.assign({},O,{ex:Object.assign({},O.ex,{["p:"+id]:true})}),sel);
 const list=btHTML({id:"plan_wbs",h:520,rowH:40,exportName:"wbs-"+id,key:"id",facets:["stt"],rows:()=>projRows(P,[id]).map(r=>Object.assign(r,{stt:r.st.t})),cols:[{k:"wbs",label:"WBS",fmt:r=>`<span class="num">${r.wbs}</span>`,val:r=>r.wbs},{k:"n",label:"Task name",fmt:r=>`<span class="wl ${r.sum?"s":""}" style="--lv:${r.lv-1}">${r.ms?'<i class="msd"></i>':""}${r.sum?"<b>"+esc(r.n)+"</b>":esc(r.n)}</span>${r.crit?' <span class="pill bad">Critical</span>':""}`,val:r=>r.n,wrap:1},{k:"es",label:"Start",fmt:r=>r.ef?fmtD(r.es):"n/a",val:r=>r.es},{k:"ef",label:"Finish",fmt:r=>r.ef?fmtD(r.ms?r.es:r.ef-1):"n/a",val:r=>r.ef},{k:"pct",label:"Done",fmt:r=>`<span class="pc" style="min-width:80px"><i style="width:${r.pct}%"></i><b>${r.pct}%</b></span>`,val:r=>r.pct},{k:"fl",label:"Float",fmt:r=>r.fl===""?"":r.fl+"d",val:r=>r.fl===""?-1:r.fl},{k:"stt",label:"Status",fmt:r=>stPill(r.st),val:r=>r.st.t},{k:"pred",label:"Waits for",val:r=>r.pred},{k:"res",label:"People and teams",val:r=>r.res}],open:x=>taskDrawer(x)});
 return `<div class="screen">${hero("Project plan",esc(pj.short),story,`<div class="row">${planPicker(id)}<button class="chip" data-rec="${pj.rec||"PR1"}" ${pj.rec?"":"hidden"}>Open in the trace</button><button class="btn" data-wbs-go="${id}">Open the WBS and task sheet</button>${stdChip("pmbok","Plan, baseline, critical path and earned value follow PMBOK terms.")}</div>`)}${lensNote()}${tiles}${views("plan",["Overview","Gantt","Milestones","Progress"],[`<div class="grid g2" style="align-items:start;margin-bottom:18px">${phaseCard(P,id)}${chain}</div><section class="card glass"><div class="cardhead"><div><h3>Work breakdown</h3><span class="muted small">Every line of the WBS. Select a row for its links, dictionary and what-ifs.</span></div></div>${list}</section>`,`<div class="row" style="gap:12px;margin-bottom:12px">${pk.html}</div>${ganttBar(O)}${ganttV("plan",rows,P,O,{h:640})}<div style="margin-top:12px">${ganttLegend()}</div>`,`<section class="card glass"><div class="cardhead"><h3>Milestones</h3><span class="muted small" data-role="story">Milestones that feed other milestones are linked.</span></div>${mileTable(P,[id],"plan_ms")}</section>`,`<div class="grid g2" style="align-items:start">${curve}${evCard(P,id)}</div>`])}${procCard("plan")}</div>`};
function evCard(P,id){const rs=rollup(P),ph=wbsOutline(id).filter(x=>x.sum&&x.lv===1).map(s=>({s,a:rs.S[s.id]||{}}));const tot=rs.PJ[id]||{cost:0,ac:0,ev:0,pv:0};
 return `<section class="card glass"><div class="cardhead"><div><h3>Earned value by phase</h3><span class="muted small" data-role="story">Planned value is budget times planned percent; earned value is budget times percent complete.</span></div></div><div class="needs">${ph.map(({s,a})=>{const cpi=a.ac>0?a.ev/a.ac:null,spi=a.pv>0?a.ev/a.pv:null;return `<button class="need" data-task="${s.id}" style="grid-template-columns:minmax(0,1fr) auto"><div><b data-role="story">${s.wbs} ${esc(s.n)}</b><span class="muted">Budget ${K$(a.cost)} · planned ${K$(a.pv)} · earned ${K$(a.ev)} · spent ${K$(a.ac)}</span></div><span style="text-align:right"><span class="pill ${spi==null?"mute":spi<.9?"warn":"good"}" data-role="metric">SPI ${spi==null?"n/a":spi.toFixed(2)}</span> <span class="pill ${cpi==null?"mute":cpi<.9?"bad":"good"}" data-role="metric">CPI ${cpi==null?"n/a":cpi.toFixed(2)}</span></span></button>`}).join("")}</div><p class="muted small" style="margin-top:10px">Project total: budget ${K$(tot.cost)}, earned ${K$(tot.ev)}, spent ${K$(tot.ac)}.</p></section>`}

/* ---------- PR-32 B4: portfolio and delivery screens under a tenant other than Atlantic Systems ----------
   window.PDTV is the small tenant view kit these screens share (screens4, mod_ppm, mod_wbs, mod_rel, mod_r15f3_time): the same
   screen, purpose and tab names, drawn only from the tenant's rows (DATA.get), in its words (DATA.term). Sample figures,
   simulated; a view with no rows of its own is a labeled gap (R18), never an Atlantic Systems row. Atlantic Systems renders as before. */
window.PDTV=(()=>{const E=esc,TEN=()=>DATA.tenant()!=="core",tw=(k,m)=>DATA.term(k,{cap:true,many:!!m});
 const C=(h,sub,ent,R,cols)=>card(h,sub,R.length?STN.table(cols.map(c=>c[0]),R.map(r=>cols.map(c=>typeof c[1]==="function"?c[1](r):E(r[c[1]]==null?"":r[c[1]])))):STN.gap(ent));
 const G=(h,s)=>card(h,"",empty(s||"No records for this in this sample company yet","Rows from another company are never shown in their place."));
 const Sc=(id,eb,h,story,tabs,top)=>{const c=Math.min(+((S.stn||{}).tab||{})[id]||0,tabs.length-1);
  return `<div class="screen stn">${STN.head(eb,h,story)}${top||""}${tabs.length>1?`<div class="stn-tabs" role="tablist" aria-label="Views">${tabs.map((t,i)=>`<button type="button" role="tab" class="chip" aria-selected="${i===c}" aria-pressed="${i===c}" data-stn-tab="${id}|${i}">${E(t[0])}</button>`).join("")}</div>`:""}<div role="tabpanel" class="stn-pane">${tabs[c][1]()}</div></div>`};
 const own=(o,b)=>r=>STN.own(r[o],r[b]),P=()=>DATA.get("projects"),pn=id=>E((P().find(p=>p.id===id)||{}).short||id||"");
 const T=p=>DATA.get("plan_tasks").filter(t=>t.part==="task"&&(!p||t.p===p)),d=w=>w==null?"":fmtD(w,1),per=k=>r=>(+r[k]||0)+"%";
 const tasks=(h,R)=>C(h,R.length+" lines","plan_tasks",R,[["WBS","wbs"],["Task",r=>`<b>${E(r.n)}</b>`],[tw("project"),r=>pn(r.p)],["Start",r=>d(r.es)],["Finish",r=>d(r.ms?r.es:r.ef-1)],["Done",per("pct")],["Owner","own"]]);
 const miles=p=>C("Milestones","Milestones on the plan","plan_tasks",T(p).filter(t=>t.ms),[["Milestone",r=>`<b>${E(r.n)}</b>`],[tw("project"),r=>pn(r.p)],["Date",r=>d(r.es)],["Done",per("pct")],["Owner","own"]]);
 const projs=h=>C(h,P().length+" in this sample company","projects",P(),[[tw("project"),r=>`<b>${E(r.n)}</b>`],["Done",per("pct")],["Health",r=>pill(r.health==="good"?"On track":r.health==="bad"?"Off track":"Watch",r.health==="good"?"good":r.health==="bad"?"bad":"warn")],["Budget",r=>STN.money(r.bac)],["Owner and backup",own("owner","backup")]]);
 const ev=p=>{const R=T(p),cost=R.reduce((a,t)=>a+(+t.cost||0),0),e=R.reduce((a,t)=>a+(+t.cost||0)*(+t.pct||0)/100,0),ac=R.reduce((a,t)=>a+(+t.ac||0),0);return {cost,e,ac,cpi:ac?e/ac:null}};
 return {E,TEN,tw,C,G,Sc,own,P,pn,T,d,per,tasks,miles,projs,ev}})();
const tvIms=()=>{const V=PDTV,P=V.P(),T=V.T(),fin=p=>Math.max(0,...V.T(p).map(t=>t.ef||0));
 return V.Sc("ims","Portfolio and delivery","Schedules across projects",P.length?`${P.length} ${DATA.term("project",{many:true})} with ${T.length} ${DATA.term("plan_task",{many:true})} on the plan. Sample data, simulated.`:"No projects in this sample company yet.",
 [["Overview",()=>V.C("Projects","Finish and progress from the plan","projects",P,[[V.tw("project"),r=>`<b>${V.E(r.n)}</b>`],["Finish",r=>fin(r.id)?V.d(fin(r.id)-1):"Not planned"],["Done",V.per("pct")],[V.tw("plan_task",1),r=>V.T(r.id).length],["Owner and backup",V.own("owner","backup")]])],
  ["Gantt",()=>V.tasks("Every "+DATA.term("plan_task")+" by start date",T.slice().sort((a,b)=>(a.es||0)-(b.es||0)))],["Milestones",()=>V.miles()],
  ["What changed",()=>V.G("What changed","No schedule baseline changes in this sample company yet.")],["Project tool coverage",()=>V.G("Project tool coverage","No connected project tools in this sample company yet.")]])};
const tvPlan=()=>{const V=PDTV,P=V.P();if(!P.length)return V.Sc("plan","Portfolio and delivery","Project plan","No projects in this sample company yet.",[["Overview",()=>V.G()]]);
 const id=P.some(p=>p.id===S.planProj)?S.planProj:P[0].id,pj=P.find(p=>p.id===id),e=V.ev(id),ph=DATA.get("plan_tasks").filter(t=>t.part==="summary"&&t.p===id&&t.lv===1);
 const pick=`<div class="row" role="group" aria-label="Project">${P.map(p=>`<button type="button" class="chip" data-planproj="${V.E(p.id)}" aria-pressed="${p.id===id}">${V.E(p.short||p.n)}</button>`).join("")}</div>`;
 return V.Sc("plan","Portfolio and delivery","Project plan: "+pj.n,`${V.E(pj.n)} is ${pj.pct||0}% done. ${V.E(pj.story||"")}`,
 [["Overview",()=>V.C("Phases","Summary lines of the plan","plan_tasks",ph,[["WBS","wbs"],["Phase",r=>`<b>${V.E(r.n)}</b>`],["Lines",r=>(r.kids||[]).length],["Owner","own"]])],["Gantt",()=>V.tasks("Work breakdown",V.T(id))],["Milestones",()=>V.miles(id)],
  ["Progress",()=>card("Earned value","Earned value is each line's budget times its percent complete (sample figures, simulated)",tiles([TL("Budget",STN.money(e.cost),"Sum of the lines","mute"),TL("Earned value",STN.money(e.e),"Budget times percent complete","mute"),TL("Actual cost",STN.money(e.ac),"Recorded on the lines","mute"),TL("Cost performance",e.cpi?e.cpi.toFixed(2):"None","Earned value divided by actual cost",e.cpi&&e.cpi<1?"warn":"good")]))]],pick)};
["ims","plan"].forEach(id=>DATA.screen(id,{mode:"data",entities:["projects","plan_tasks"],note:"screens4 (PR-32 B4)"}));
