/* ---------- Product log ---------- */
const LOGALL=()=>LOG0.concat(LOGX);
const LST={Done:"good","In progress":"info",Open:"warn",Declined:"mute"};
function logMd(){return "| ID | Kind | Area | Request | Status | Version |\n|---|---|---|---|---|---|\n"+LOGALL().map(r=>`| ${r[0]} | ${r[1]} | ${r[2]} | ${r[3].replace(/\|/g,"/")} | ${r[4]} | ${r[5]==="\u2014"?"":r[5]} |`).join("\n")}
function logPane(){const L=LOGALL().filter(r=>(S.logf==="all"||r[4]===S.logf)&&(S.logk==="all"||r[1]===S.logk)),kinds=[...new Set(LOGALL().map(r=>r[1]))];const id=pid();
 return `<div class="card glass"><div class="cardhead"><div><h3>Register</h3><span class="muted small">Every request and every piece of design feedback, with where it landed</span></div><div class="row"><button class="btn" popovertarget="${id}">Export as Markdown</button></div></div>
 <div class="row" style="gap:8px;margin-bottom:14px"><div class="recchips">${["all","Done","In progress","Open"].map(s=>`<button class="chip" data-logf="${s}" aria-pressed="${S.logf===s}">${s==="all"?"All statuses":s}</button>`).join("")}</div><div class="recchips">${["all",...kinds].map(s=>`<button class="chip" data-logk="${s}" aria-pressed="${S.logk===s}">${s==="all"?"All kinds":s}</button>`).join("")}</div></div>
 <div class="needs">${L.map(r=>`<div class="need logrow" style="grid-template-columns:auto 1fr auto"><div><span class="pill mute">${r[0]}</span></div><div><b data-role="story">${esc(r[3])}</b><span class="muted">${esc(r[1])} · ${esc(r[2])}${r[5]&&r[5]!=="\u2014"?" · landed in "+r[5]:""}</span></div><span class="pill ${LST[r[4]]||"mute"}">${r[4]}</span></div>`).join("")||'<span class="muted">Nothing matches.</span>'}</div></div>
 <div popover id="${id}" class="pop glass" style="width:min(720px,92vw)"><div class="eyebrow">Markdown</div><h3>Copy into the vault</h3><pre class="mdpre" id="mdout">${esc(logMd())}</pre><div class="row" style="margin-top:12px"><button class="btn primary" data-logcopy="1">Copy</button><button class="btn" popovertarget="${id}" popovertargetaction="hide">Close</button></div></div>`}
function addPane(){return `<div class="grid g2" style="align-items:start"><div class="card glass"><div class="cardhead"><div><h3>Add feedback</h3><span class="muted small">Anything you notice, from a color to a missing feature. It goes into the register as Open.</span></div></div><div class="recchips" style="margin-bottom:12px">${["Feature","Design","Clarity","Idea","Question"].map(k=>`<button class="chip" data-newkind="${k}" aria-pressed="${S.newKind===k}">${k}</button>`).join("")}</div><div class="stack"><input class="txtin" id="logArea" placeholder="Where (screen or area)" aria-label="Area" autocomplete="off"><input class="txtin" id="logTxt" placeholder="What should change, and why" aria-label="Feedback" autocomplete="off"><div><button class="btn primary" data-logadd="1">Add to the register</button></div></div><p class="muted small" style="margin-top:12px">${LOGX.length?LOGX.length+" added in this browser. ":""}In the real platform this writes to the product backlog. In the prototype it lives in your browser and in the vault register that Claude keeps after each round.</p></div>
 <div class="card glass"><div class="cardhead"><div><h3>Signals from usage</h3><span class="muted small">Patterns in the audit trail that deserve research</span></div></div><div class="needs">${TRENDS.map(x=>`<div class="need" style="grid-template-columns:1fr auto"><div><b data-role="story">${esc(x.ev)}</b><span class="muted">${esc(x.idea)}</span></div><button class="btn" data-trend2="${x.id}">Add to register</button></div>`).join("")}</div></div></div>`}
function relPane(){const L=LOGALL();return `<div class="timeline">${VERS.slice().reverse().map(v=>{const items=L.filter(r=>r[5]===v[0]);return `<div class="card glass tlcard"><div class="cardhead"><div><span class="eyebrow">${v[1]} · ${v[0]}</span><h3>${esc(v[2])}</h3><span class="muted small">${esc(v[3])}</span></div><span class="pill info">${items.length} items</span></div><div class="needs">${items.slice(0,8).map(r=>`<div class="muted small">${r[0]} · ${esc(r[3].length>110?r[3].slice(0,108)+"…":r[3])}</div>`).join("")}${items.length>8?`<div class="muted small">and ${items.length-8} more</div>`:""}</div></div>`}).join("")}</div>`}
_R.log=()=>{const L=LOGALL(),n=s=>L.filter(r=>r[4]===s).length;
 const story=`<b>${L.length}</b> requests so far: <b>${n("Done")}</b> shipped, <b>${n("In progress")}</b> in progress and <b>${n("Open")}</b> waiting. Nothing you say about the design is lost.`;
 return `<div class="screen">${hero("Product log","Everything you asked for",story,`<div class="row">${whyPop("Every round of feedback becomes a row here with a status and the version it landed in. Claude updates the register in the vault at the end of each session, so the next build starts from it.")}</div>`)}${lensNote()}<div class="grid g4" style="margin-bottom:18px">${tl("Requests",L.length,VERS.length+" releases so far","good")}${tl("Shipped",n("Done"),Math.round(n("Done")/L.length*100)+"% of the register","good")}${tl("In progress",n("In progress"),"Planned for this release","warn")}${tl("Waiting",n("Open"),"Open for your decision","warn")}</div>${views("log",["Register","Add feedback","Releases"],[logPane(),addPane(),relPane()])}</div>`};

