BLK.ims=P=>{const Pl=plan("now");syncSpi();return `<section class="card glass"><div class="cardhead"><div><h3>Portfolio schedule</h3><span class="muted small" data-role="story">Lumen's late indexer holds up two projects. Standards go live is ${lateTxt(Pl.R.p1_9.es-BASE.R.p1_9.es)}.</span></div>${fchip("m_spi")}</div><div class="needs">${PROJ.map(p=>{const f=projFin(Pl,p.id),d=f-projFin(BASE,p.id),e=evm(Pl,p.id);return `<button class="need" data-planto="${p.id}" style="grid-template-columns:1fr auto"><div><b data-role="story">${esc(p.n)}</b><span class="muted">Finishes <b class="num" data-role="metric">${fmtD(fin1(Pl,p.id))}</b> · ${Math.round(e.ev*100)}% done</span></div><span class="pill ${pcls(d)}" data-role="metric">${lateTxt(d)}</span></button>`}).join("")}</div><div class="row" style="margin-top:12px"><button class="btn" data-nav="ims">Open the master schedule</button></div></section>`};
