const _si=searchIndex;searchIndex=function(){const o=_si();DEMAND.forEach(d=>o.push({g:"Demand",t:d.n,m:K$(d.cost),c:"--u3",f:()=>{go("port");demandDrawer(d.id)},k:d.why}));return o};
const _ask=ask;ask=function(q){const l=q.toLowerCase();
 if(/\bwbs\b|work breakdown|task sheet|network diagram|resource sheet|task usage|earned value by|baseline compare|which milestones|milestones? (that )?feed|feeds? (the )?(beta|pilot|go live|milestone)|predecessor|successor/.test(l)){for(const fn of ASKX){try{if(fn(q))return}catch(e){}}}
 if(/^(log|add)( this| feedback)?[:\- ]+(.+)/.test(l)&&/feedback|log/.test(l)){const t=q.replace(/^(log|add)( this| feedback)?[:\- ]+/i,"");addLog("Feature","Chat",t);return say(q,{t:"Added to the product log as Open: "+t,steps:["Created a register item","Recorded it in the audit trail"],act:()=>go("log")})}
 if(/lumen.*(slip|late)|what if.*(indexer|lumen)/.test(l)){S.ims.scen="lumen5";go("ims");return say(q,{t:"With 5 more days on the search indexer, the Standards beta moves to "+fmtD(plan("lumen5").R.p1_5.es)+" and the Taxonomy pilot to "+fmtD(plan("lumen5").R.p2_5.es)+". I opened the master schedule with that scenario applied.",steps:["Added 5 work days to the indexer","Recalculated all four projects","Compared with the baseline"]})}
 if(/gantt|critical path|master schedule|baseline/.test(l)){go("ims");return say(q,{t:"Here is the integrated master schedule. Red bars are the critical path.",steps:["Opened the master schedule"]})}
 if(/demand|priorit|fund(ing)?|intake|portfolio/.test(l)&&!/impact/.test(l)){go("port");return say(q,{t:"Here is demand ranked by priority score, with the funding line for your current envelope.",steps:["Opened Demand and priorities"]})}
 return _ask(q)};
function addLog(kind,area,text){const id="U"+String(LOGX.length+1).padStart(2,"0");LOGX.push([id,kind,area||"General",text,"Open",""]);U.store.set(LOGKEY,LOGX);audit("logged feedback",id+" · "+text)}

document.addEventListener("click",e=>{const t=e.target.closest("[data-dem],[data-task],[data-planto],[data-planproj],[data-slip],[data-imsscen],[data-imsproj],[data-imsopt],[data-gx-tog],[data-imslv],[data-imslv-ex],[data-wbs-go],[data-advance],[data-dapp],[data-merge],[data-capdem],[data-logf],[data-logk],[data-newkind],[data-logadd],[data-logcopy],[data-trend2]");if(!t)return;const d=t.dataset;
 if(d.dem)return demandDrawer(d.dem);
 if(d.task){if(!(S.screen==="ims"||S.screen==="plan")&&false)go("ims");return taskDrawer(d.task)}
 if(d.planto||d.planproj){S.planProj=d.planto||d.planproj;if(d.planto&&S.screen!=="plan"){closeDrawer();return go("plan")}return render()}
 if(d.slip){const [id,n]=d.slip.split(":");if(id==="reset")S.imsSlip={};else if(+n===0)delete S.imsSlip[id];else S.imsSlip[id]=(S.imsSlip[id]||0)+ +n;S.ims.scen="now";audit("what-if on schedule",id+" +"+n+"d");closeDrawer();if(S.screen!=="ims"&&S.screen!=="plan")go("ims");else render();return}
 if(d.gxTog){const k=d.gxTog,O=S.ims;O.ex=O.ex||{};const cur=k.startsWith("p:")?gxOpen(O,k.slice(2),true):gxOpen(O,wbsLn(k),false);O.ex[k]=!cur;return render()}
 if(d.imslv){S.ims.lv=+d.imslv;S.ims.ex={};audit("showed schedule levels",d.imslv);return render()}
 if(d.imslvEx){S.ims.lv=d.imslvEx==="open"?9:1;S.ims.ex={};return render()}
 if(d.wbsGo){S.mpSel.wbs_proj=[d.wbsGo];if(S.wbs)S.wbs.tab=S.wbs.tab||"sheet";return go("ppm_wbs")}
 if(d.imsscen){S.ims.scen=d.imsscen;audit("applied schedule scenario",d.imsscen);return S.screen==="ims"?render():go("ims")}
 if(d.imsproj){S.ims.proj=d.imsproj;return render()}
 if(d.imsopt){const k=d.imsopt;if(k[0]==="z")S.ims.zoom=+k.slice(1);else S.ims[k]=!S.ims[k];return render()}
 if(d.advance){S.dst[d.advance]=Math.min(3,Math.max(DEMAND.find(x=>x.id===d.advance).st,S.dst[d.advance]||0)+1);audit("moved demand to "+DSTAGES[S.dst[d.advance]],d.advance);demandDrawer(d.advance);return render()}
 if(d.dapp){const [id,v]=d.dapp.split(":");S.dapp[id]=v;audit(v.toLowerCase()+" demand",id);closeDrawer();return render()}
 if(d.merge){const [a,b]=d.merge.split(":");S.merged[a]=b;audit("merged demand",a+" into "+b);closeDrawer();return render()}
 if(d.capdem){S.capDemand=!S.capDemand;S.v.port=2;return render()}
 if(d.logf){S.logf=d.logf;return render()}if(d.logk){S.logk=d.logk;return render()}if(d.newkind){S.newKind=d.newkind;S.v.log=1;return render()}
 if(d.logadd){const tx=($("#logTxt")||{}).value||"",ar=($("#logArea")||{}).value||"";if(!tx.trim()){$("#logTxt").focus();return}addLog(S.newKind,ar.trim(),tx.trim());S.v.log=0;S.logf="Open";return render()}
 if(d.logcopy){const x=$("#mdout").textContent;const ok=()=>{t.textContent="Copied"};try{navigator.clipboard.writeText(x).then(ok,()=>{const r=document.createRange();r.selectNodeContents($("#mdout"));const s=getSelection();s.removeAllRanges();s.addRange(r);t.textContent="Selected, press Copy"})}catch(er){}return}
 if(d.trend2){const x=TRENDS.find(y=>y.id===d.trend2);addLog("Idea","Usage signal",x.ev);t.textContent="Added";t.disabled=true;return}});
document.addEventListener("input",e=>{const t=e.target;if(t.dataset&&t.dataset.rng){const k=t.dataset.rng;if(k==="env")S.env=+t.value;else if(k==="cap")S.cap=+t.value;else S.w[k]=+t.value;const lab=t.previousElementSibling&&t.previousElementSibling.querySelector("b");if(lab&&k==="env")lab.textContent=K$(S.env);else if(lab&&k==="cap")lab.textContent=S.cap+" pm"}});
