/* CL-76: one index of open WBS assignments by person and one schedule per pass (workFor.index), not one plan per person */
const cl76WbsIdx=()=>{const m=new Map();const U=ulist();U.forEach(t=>{if(!(t.pct<100))return;new Set((t.asg||[]).map(a=>a[0])).forEach(n=>{if(t.own===n)return;let a=m.get(n);if(!a)m.set(n,a=[]);if(a.length<60)a.push(t)})});
 const out=new Map();if(!m.size)return out;const P=plan("now",U);m.forEach((L,n)=>out.set(n,L.map(t=>cl76WbsRow(P,t,n))));return out};
const cl76WbsBy=window.workFor&&workFor.index?workFor.index(cl76WbsIdx):n=>cl76WbsIdx().get(n)||[];
WORK.push({kind:"WBS assignments",tag:"WBS",fn:(n)=>cl76WbsBy(n)});
function cl76WbsRow(P,t,n){{const r=P.R[t.id],a=(t.asg||[]).find(x=>x[0]===n);return {id:t.id,t:(wbsLn(t.id)||{wbs:""}).wbs+" "+t.n,sub:((pr(t.p)||{}).short||t.p)+" · "+a[1]+"% assigned · "+t.pct+"% done",due:r?fmtD(t.ms?r.es:r.ef-1):"",st:r&&r.fl<=0?"bad":t.pct>0?"info":"mute",hrs:Math.round(a[1]/100*Math.min(t.dur,5)*HRS),go:()=>{go("plan");taskDrawer(t.id)}}}}
SEARCHX.push(()=>{const P=plan("now",ulist());const out=[];UPROJ().forEach(pj=>{wbsOutline(pj.id).forEach(it=>{if(out.length>3000)return;out.push({g:"WBS lines",t:it.wbs+" "+it.n,m:pj.short+(it.sum?" · summary":it.ms?" · milestone":""),c:pj.c,f:()=>{S.planProj=pj.id;go("ims");taskDrawer(it.id)},k:[it.dv,it.note,it.own,it.acc].filter(Boolean).join(" ")})})});return out});
